let shapes = [];
const shapesNum = 5000;
let sMax;

function setup() {
  createCanvas(windowWidth, windowHeight);

  sMax = max(width, height) * 0.3;

  for (let i = 0; i < shapesNum; i++) {
    shapes.push(new Shape(i));
  }

  background("#E7ECF2");
}

function draw() {
  background("#E7ECF230");

  noStroke();
  fill(0);

  for (let i = 0; i < shapes.length; i++) {
    shapes[i].move();
    shapes[i].display();
  }
}

class Shape {
  constructor(i) {
    this.i = i * 0.01;
    this.A = 0;
    this.B = 0;
    this.S = i % sMax;
  }

  move() {
    this.S += 1;
    if (this.S > sMax) {
      this.S = 0;
    }
  }

  display() {
    this.A = (cos(this.i * 3) - cos(this.i * 6) + 9) * 0.45;
    this.B = this.i / 2 + (sin(this.i * 3) - sin(this.i * 6)) / 3;

    fill(255 * sin(this.B * 10 + frameCount * 0.1), 100, 150);

    circle(
      this.S * this.A * cos(this.B) + width / 2,
      this.S * this.A * sin(this.B) + height / 2,
      this.S * 0.2 * sin(this.i * 11)
    );
  }
}
